import { diag, SpanStatusCode, trace } from '@opentelemetry/api';
import { safeJsonStringify } from '../utils/safeJsonStringify.js';
import { sessionId } from '../utils/session.js';
import {
  GeminiCliOperation,
  SERVICE_DESCRIPTION,
  SERVICE_NAME,
  GEN_AI_AGENT_DESCRIPTION,
  GEN_AI_AGENT_NAME,
  GEN_AI_CONVERSATION_ID,
  GEN_AI_INPUT_MESSAGES,
  GEN_AI_OPERATION_NAME,
  GEN_AI_OUTPUT_MESSAGES,
} from './constants.js';

const TRACER_NAME = 'gemini-cli';
const TRACER_VERSION = 'v1';

/**
 * Metadata for a span.
 *
 * The callback passed to {@link runInDevTraceSpan} mutates this object to
 * describe the traced operation; its contents are flushed onto the span when
 * the span is finalized.
 */
export interface SpanMetadata {
  /** The name of the span. */
  name?: string;
  /** Additional attributes for the span. */
  attributes: Record<string, any>;
  /** The input to the span. */
  input?: any;
  /** The output of the span. */
  output?: any;
  /** An error that occurred during the span. */
  error?: any;
}

/**
 * Options controlling how {@link runInDevTraceSpan} creates a span.
 */
export interface RunInDevTraceSpanOptions {
  /** The high-level operation being traced. Used as the span name. */
  operation: GeminiCliOperation;
  /**
   * When `true`, the span is not automatically ended when the callback
   * resolves. The caller is responsible for calling `endSpan` (e.g. once a
   * stream has been fully consumed).
   */
  noAutoEnd?: boolean;
  /** Initial attributes to seed the span metadata with. */
  attributes?: Record<string, any>;
}

/**
 * Runs a function inside a new, active OpenTelemetry span.
 *
 * The `metadata` object provided to the callback is used to populate the span's
 * attributes, input/output messages, and status when the span is finalized.
 * Tracing is always active.
 *
 * @example
 * ```typescript
 * runInDevTraceSpan(
 *   { operation: GeminiCliOperation.ToolCall },
 *   async ({ metadata }) => {
 *     metadata.input = { foo: 'bar' };
 *     // ... do work ...
 *     metadata.output = { result: 'baz' };
 *     metadata.attributes['my.custom.attribute'] = 'some-value';
 *   },
 * );
 * ```
 *
 * @param opts The options for the span.
 * @param fn The function to run in the span.
 * @returns A promise resolving to the result of the function.
 */
export async function runInDevTraceSpan<R>(
  opts: RunInDevTraceSpanOptions,
  fn: (args: { metadata: SpanMetadata; endSpan: () => void }) => Promise<R>,
): Promise<R> {
  const { operation, noAutoEnd, attributes } = opts;

  const tracer = trace.getTracer(TRACER_NAME, TRACER_VERSION);
  return tracer.startActiveSpan(operation, async (span) => {
    const meta: SpanMetadata = {
      name: operation,
      attributes: {
        [GEN_AI_OPERATION_NAME]: operation,
        [GEN_AI_AGENT_NAME]: SERVICE_NAME,
        [GEN_AI_AGENT_DESCRIPTION]: SERVICE_DESCRIPTION,
        [GEN_AI_CONVERSATION_ID]: sessionId,
        ...attributes,
      },
    };

    const endSpan = () => {
      try {
        if (meta.input !== undefined) {
          span.setAttribute(
            GEN_AI_INPUT_MESSAGES,
            safeJsonStringify(meta.input),
          );
        }
        if (meta.output !== undefined) {
          span.setAttribute(
            GEN_AI_OUTPUT_MESSAGES,
            safeJsonStringify(meta.output),
          );
        }
        for (const [key, value] of Object.entries(meta.attributes)) {
          if (value !== undefined && value !== null) {
            span.setAttribute(key, value);
          }
        }
        if (meta.error) {
          span.setStatus({
            code: SpanStatusCode.ERROR,
            message: getErrorMessage(meta.error),
          });
          span.recordException(
            meta.error instanceof Error
              ? meta.error
              : new Error(getErrorMessage(meta.error)),
          );
