[metadata] {"type": "text", "file": {"filePath": "/workspace/repo/packages/core/src/telemetry/trace.ts", "content": " * @param fn The function to run in the span.\n * @returns A promise resolving to the result of the function.\n */\nexport async function runInDevTraceSpan<R>(\n  opts: RunInDevTraceSpanOptions,\n  fn: (args: { metadata: SpanMetadata; endSpan: () => void }) => Promise<R>,\n): Promise<R> {\n  const { operation, noAutoEnd, attributes } = opts;\n\n  const tracer = trace.getTracer(TRACER_NAME, TRACER_VERSION);\n  return tracer.startActiveSpan(operation, async (span) => {\n    const meta: SpanMetadata = {\n      name: operation,\n      attributes: {\n        [GEN_AI_OPERATION_NAME]: operation,\n        [GEN_AI_AGENT_NAME]: SERVICE_NAME,\n        [GEN_AI_AGENT_DESCRIPTION]: SERVICE_DESCRIPTION,\n        [GEN_AI_CONVERSATION_ID]: sessionId,\n        ...attributes,\n      },\n    };\n\n    const endSpan = () => {\n      try {\n        if (meta.input !== undefined) {\n          span.setAttribute(\n            GEN_AI_INPUT_MESSAGES,\n            safeJsonStringify(meta.input),\n          );\n        }\n        if (meta.output !== undefined) {\n          span.setAttribute(\n            GEN_AI_OUTPUT_MESSAGES,\n            safeJsonStringify(meta.output),\n          );\n        }\n        for (const [key, value] of Object.entries(meta.attributes)) {\n          if (value !== undefined && value !== null) {\n            span.setAttribute(key, value);\n          }\n        }\n        if (meta.error) {\n          span.setStatus({\n            code: SpanStatusCode.ERROR,\n            message: getErrorMessage(meta.error),\n          });\n          span.recordException(\n            meta.error instanceof Error\n              ? meta.error\n              : new Error(getErrorMessage(meta.error)),\n          );\n        } else {\n          span.setStatus({ code: SpanStatusCode.OK });\n        }\n        span.end();\n      } catch (e) {\n        // Setting span attributes/status can throw (e.g. invalid attribute\n        // values). Ensure the span is still terminated so it is never leaked.\n        diag.error('Error setting span attributes in endSpan', e);\n        span.setStatus({\n          code: SpanStatusCode.ERROR,\n          message: `Error in endSpan: ${getErrorMessage(e)}`,\n        });\n        span.end();\n      }\n    };\n\n    try {\n      const result = await fn({ metadata: meta, endSpan });\n      if (!noAutoEnd) {\n        endSpan();\n      }\n      return result;\n    } catch (e) {\n      meta.error = e;\n      // Always finalize the span on error, even for `noAutoEnd` operations,\n      // so it is recorded correctly and never leaked.\n      endSpan();\n      throw e;\n    }\n  });\n}\n\n/**\n * Gets the error message from an error object.", "numLines": 85, "startLine": 85, "totalLines": 183}}
